import json,numpy as np
from PIL import Image
m=json.load(open('/app/output/lift2/meta.json')); c='side'; im=np.array(Image.open('/app/output/lift2/side.png'));d=np.load('/app/output/lift2/side_depth.npy')[0].astype(float);K=np.array(m['cameras'][c]['intrinsic_cv']);P=np.array(m['cameras'][c]['cam2world_gl']);
def w(x,y):
 z=d[y,x];ca=np.array([(x-K[0,2])/K[0,0]*z,-(y-K[1,2])/K[1,1]*z,-z]);return np.round(P[:3,:3]@ca+P[:3,3],3)
for y in [190,195,200,205,210,215,220,225]:
 for x in [195,200,205,210,215,220]:
  print((x,y),im[y,x],d[y,x],w(x,y))
